package com.bank.spark.model;

// The four security layers and whether each is enabled.
public class SecurityPosture {
    private final boolean authentication;    // Kerberos / tokens + RPC auth
    private final boolean authorization;     // Ranger / RBAC / ACLs
    private final boolean encryptionInTransit; // SSL/TLS RPC + shuffle
    private final boolean encryptionAtRest;  // HDFS/S3 encryption
    private final boolean networkIsolation;  // private subnets / security groups

    public SecurityPosture(boolean authentication, boolean authorization,
                           boolean encryptionInTransit, boolean encryptionAtRest,
                           boolean networkIsolation) {
        this.authentication = authentication;
        this.authorization = authorization;
        this.encryptionInTransit = encryptionInTransit;
        this.encryptionAtRest = encryptionAtRest;
        this.networkIsolation = networkIsolation;
    }

    public boolean isAuthentication() { return authentication; }
    public boolean isAuthorization() { return authorization; }
    public boolean isEncryptionInTransit() { return encryptionInTransit; }
    public boolean isEncryptionAtRest() { return encryptionAtRest; }
    public boolean isNetworkIsolation() { return networkIsolation; }
}
