package com.bank.spark.service;

import com.bank.spark.model.SecurityPosture;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Evaluates a cluster's posture against the production baseline (all layers).
public class PostureChecker {

    private static final Logger log = Logger.getLogger(PostureChecker.class.getName());

    public List<String> missingLayers(SecurityPosture p) {
        List<String> gaps = new ArrayList<>();
        if (!p.isAuthentication())       gaps.add("AUTHENTICATION (Kerberos/tokens + RPC auth)");
        if (!p.isAuthorization())        gaps.add("AUTHORIZATION (Ranger/RBAC/ACLs)");
        if (!p.isEncryptionInTransit())  gaps.add("ENCRYPTION IN TRANSIT (SSL/TLS RPC + shuffle)");
        if (!p.isEncryptionAtRest())     gaps.add("ENCRYPTION AT REST (HDFS/S3)");
        if (!p.isNetworkIsolation())     gaps.add("NETWORK ISOLATION (private subnet / SG)");
        return gaps;
    }

    public boolean meetsBaseline(SecurityPosture p) {
        List<String> gaps = missingLayers(p);
        if (gaps.isEmpty()) {
            log.info("Posture meets the production baseline (all four layers present)");
            return true;
        }
        for (String g : gaps) log.severe(() -> "MISSING layer: " + g);
        return false;
    }
}
