package com.bank.spark;

import com.bank.spark.model.SecurityPosture;
import com.bank.spark.service.PostureChecker;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: evaluate two clusters against the security baseline.
public class SecurityPostureDemo {

    private static final Logger log = Logger.getLogger(SecurityPostureDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        PostureChecker checker = new PostureChecker();

        // Hardened production cluster: all four layers enabled.
        SecurityPosture prod = new SecurityPosture(true, true, true, true, true);
        log.info("--- production cluster ---");
        log.info(() -> "Meets baseline? " + checker.meetsBaseline(prod));

        // Misconfigured cluster: missing authorization and network isolation.
        SecurityPosture weak = new SecurityPosture(true, false, true, true, false);
        log.info("--- misconfigured cluster ---");
        boolean ok = checker.meetsBaseline(weak);
        log.info(() -> "Meets baseline? " + ok);

        log.info("Security posture demo complete.");
    }
}
